import numpy as np
# nets as printed: (col,row) -> label, row grows downward
nets = {'A': {(0,0):5,(1,0):1,(1,1):4,(1,2):6,(1,3):2,(2,3):3}, 'B': {(0,0):5,(1,0):1,(1,1):4,(1,2):2,(1,3):6,(2,3):3},
        'C': {(0,0):5,(1,0):1,(1,1):3,(1,2):2,(1,3):4,(2,3):6}, 'D': {(0,0):5,(1,0):1,(1,1):4,(1,2):6,(1,3):3,(2,3):2}}
views = [(5,4,1), (4,6,3), (2,6,5)]  # (top, front-left, front-right): counter-clockwise seen from outside
V = {'U':(0,0,1),'D':(0,0,-1),'E':(1,0,0),'W':(-1,0,0),'N':(0,1,0),'S':(0,-1,0)}
ROLL = {'E':{'D':'E','E':'U','U':'W','W':'D'}, 'W':{'D':'W','W':'U','U':'E','E':'D'},
        'N':{'D':'N','N':'U','U':'S','S':'D'}, 'S':{'D':'S','S':'U','U':'N','N':'D'}}  # new_dir -> old_dir
roll = lambda st, d: {k: st[ROLL[d].get(k, k)] for k in st}
def fold(net):  # roll a cube over the net lying printed side DOWN (printed side ends up outside);
    step = {(1,0):'W', (-1,0):'E', (0,1):'S', (0,-1):'N'}  # seen from below: page-right = West, page-down = South
    s = next(iter(net)); lab = {}; seen = {s}
    def dfs(c, st):
        lab[st['D']] = net[c]
        for (dc, dr), d in step.items():
            nb = (c[0]+dc, c[1]+dr)
            if nb in net and nb not in seen: seen.add(nb); dfs(nb, roll(st, d))
    dfs(s, {k: k for k in V}); return {lab[k]: np.array(V[k]) for k in V}
ok = lambda N: all(np.linalg.det(np.array([N[t], N[l], N[r]])) > 0 for t, l, r in views)
for k, net in nets.items():
    N = fold(net); print(k, sorted((a, b) for a in N for b in N if a < b and N[a] @ N[b] == -1), ok(N))
# A [(1,6),(2,4),(3,5)] True; B, C, D False
print('mirror of A:', ok(fold({(2 - c, r): v for (c, r), v in nets['A'].items()})))  # False (handedness control)
